I extended a bit the code I wrote in the VS notetag thread. Now it has checks for magical and certain hit. I don't think you need to check "vs all" attacks, because that doesn't even go to selection screen, right? I also made it create just one sprite which it shows and hides and moves. But yeah, I'm not sure if you need to destroy the sprite at battle end or if it does it automatically and if it'd be better to use the addchild to some other place. Maybe someone else can answer those. You need to add this stuff as a plugin file. You can change the position by adding/subtracting where it sets the sprite x and y positions. For your other question, you can check the code in the rpg maker js files.
Window_BattleEnemy.prototype.initialize = function(rect) {
this._enemies = [];
Window_Selectable.prototype.initialize.call(this, rect);
this.refresh();
const bitmap = new Bitmap(200, 100);
bitmap.fontSize = 24;
this._hitPercentSprite = new Sprite();
this._hitPercentSprite.bitmap = bitmap;
SceneManager._scene.addChild(this._hitPercentSprite);
this._hitPercentSprite.hide();
this.hide();
};
Window_BattleEnemy.prototype.show = function() {
this.refresh();
this.forceSelect(0);
$gameTemp.clearTouchState();
Window_Selectable.prototype.show.call(this);
if (this._hitPercentSprite && this.enemy()) {
this._hitPercentSprite.x = this.enemy().screenX();
this._hitPercentSprite.y = this.enemy().screenY()-50;
this._hitPercentSprite.show();
}
};
Window_BattleEnemy.prototype.hide = function() {
Window_Selectable.prototype.hide.call(this);
$gameTroop.select(null);
if (this._hitPercentSprite) {
this._hitPercentSprite.hide();
}
};
Window_BattleEnemy.prototype.select = function(index) {
this._index = index;
this.refreshCursor();
this.callUpdateHelp();
if (this._hitPercentSprite && BattleManager._currentActor && BattleManager.inputtingAction() && BattleManager.inputtingAction().item() && this.enemy() && !BattleManager.inputtingAction().isItem()) {
this._hitPercentSprite.bitmap.clear();
const currentAction = BattleManager.inputtingAction();
const currentActionItem = currentAction.item();
const currentActorHit = BattleManager._currentActor.hit;
const enemyEva = this.enemy().eva;
const enemyMev = this.enemy().mev;
const successRate = currentActionItem.successRate / 100;
const enemyX = this.enemy().screenX();
const enemyY = this.enemy().screenY()-50;
let hitRate = "";
if (currentAction.isCertainHit()) {
hitRate = "Guaranteed hit";
} else if (currentAction.isMagical()) {
hitRate = (Math.round((successRate*(currentActorHit - enemyMev)*100))).toString() + "%";
} else {
hitRate = (Math.round((successRate*(currentActorHit - enemyEva)*100))).toString() + "%";
}
this._hitPercentSprite.bitmap.drawText(hitRate, 0, 0, 200, 100, "left");
this._hitPercentSprite.x = this.enemy().screenX();
this._hitPercentSprite.y = this.enemy().screenY()-50;
}
};

